/** Validate registered views and formers against one assembly's read vocabulary. */
import { asMarker, liveOf } from "./ir.js";
import { isPlainObject } from "./matchers.js";
import { assertFormerBindings } from "./former-bindings.js";
import { foldFormerNode } from "./schema.js";
import { assertNoOrphanedOpens, scheduleBlock } from "./schedule.js";
import { walkValueTree } from "./value-tree.js";
import { viewLineIR } from "./view-lowering.js";
import { assertViewShape } from "./views.js";
export class ViewFormerValidator {
    definitions;
    formable = new WeakSet();
    usableViews = new WeakSet();
    constructor(definitions) {
        this.definitions = definitions;
    }
    assertFormable(ref) {
        if (this.formable.has(ref))
            return;
        const site = ref.formerName;
        assertFormerBindings(ref.body, new Set(ref.ins), site, {
            promiseOf: (line, diagnosticSite) => this.lineRefPromise(line, diagnosticSite),
        });
        foldFormerNode(ref.body, {
            query: (query) => this.definitions.resolver.query(query.concept, query.query, `Former "${site}"`),
            pattern: (pattern) => this.assertPatternUsable(pattern, site, "Former"),
            node: (node) => {
                if (node.node !== "former")
                    return;
                const nested = liveOf(node) ?? this.definitions.formerNamed(node.former);
                if (nested === undefined) {
                    throw new Error(`Former "${site}": named former "${node.former}" is not registered.`);
                }
            },
            op: (op) => {
                if (op.op === "earlier" || op.op === "now") {
                    const word = op.op === "earlier" ? "earlier" : "now";
                    throw new Error(`Former "${site}": a former answers from standing state — ${word}(...) cannot appear in its selections.`);
                }
                this.assertOpUsable(op, site, "Former");
            },
            splice: (use) => {
                const fragment = liveOf(use);
                if (fragment !== undefined)
                    this.assertFormable(fragment);
                else if (this.definitions.formerNamed(use.fragment) === undefined) {
                    throw new Error(`Former "${site}": spliced fragment "${use.fragment}" resolves against ` +
                        "the engine's registered formers — register dependencies first.");
                }
            },
        });
        this.formable.add(ref);
    }
    assertViewUsable(ref) {
        if (this.usableViews.has(ref))
            return;
        const site = ref.viewName;
        const ins = ref.ins;
        const outs = ref.outs;
        for (const block of ref.alternatives) {
            const scheduled = scheduleBlock(block, new Set(ins), `View "${site}"`);
            for (const out of outs) {
                if (!scheduled.bound.has(out)) {
                    throw new Error(`View "${site}": an alternative never binds the declared output "${out}".`);
                }
            }
            assertNoOrphanedOpens(scheduled, [...ins, ...outs], `View "${site}"`);
            for (const op of block) {
                const kind = op.op;
                if (kind === "earlier" || kind === "now") {
                    const word = kind === "earlier" ? "earlier" : "now";
                    throw new Error(`View "${site}": a view answers from standing state, not from the ` +
                        `current flow — ${word}(...) belongs to a reaction's own where.`);
                }
                this.assertOpUsable(op, site, "View");
                if (viewLineIR(op)) {
                    const nested = liveOf(op) ?? this.definitions.viewNamed(op.view);
                    if (nested !== undefined)
                        this.assertViewUsable(nested);
                }
            }
        }
        assertViewShape(`View "${site}"`, outs, ref.promise, ref.holdsPredicate);
        this.usableViews.add(ref);
    }
    assertOpUsable(op, site, kind) {
        switch (op.op) {
            case "find":
            case "whether":
            case "no":
                if (viewLineIR(op)) {
                    if (liveOf(op) === undefined && this.definitions.viewNamed(op.view) === undefined) {
                        throw new Error(`${kind} "${site}": view "${op.view}" is not registered — ` +
                            "registerViews(...) before the reactions that ask it.");
                    }
                }
                else if (op.query !== undefined) {
                    this.definitions.resolver.query(op.query.concept, op.query.query, `${kind} "${site}"`);
                }
                this.assertPatternUsable(op.in, site, kind);
                break;
            case "count":
                this.definitions.resolver.query(op.query.concept, op.query.query, `${kind} "${site}"`);
                this.assertPatternUsable(op.in, site, kind);
                break;
            case "holds": {
                const installed = liveOf(op);
                if (installed !== undefined) {
                    this.definitions.resolveAuthoredComputation(installed, `${kind} "${site}"`);
                }
                else {
                    this.definitions.resolver.computation(op.computation, `${kind} "${site}"`);
                }
                this.assertPatternUsable(op.in, site, kind);
                break;
            }
            case "compute": {
                const installed = liveOf(op);
                if (installed !== undefined) {
                    this.definitions.resolveAuthoredComputation(installed, `${kind} "${site}"`);
                }
                else {
                    this.definitions.resolver.computation(op.computation, `${kind} "${site}"`, true);
                }
                this.assertPatternUsable(op.in, site, kind);
                if (typeof op.out !== "string")
                    this.assertPatternUsable(op.out, site, kind);
                break;
            }
            case "custom":
                if (liveOf(op) === undefined) {
                    throw new Error(`${kind} "${site}": a custom op (${op.fnRef}) is opaque code and cannot be ` +
                        "re-registered from data.");
                }
                break;
        }
    }
    assertPatternUsable(pattern, site, kind) {
        walkValueTree(pattern, (node) => {
            if (!isPlainObject(node))
                return;
            const marker = asMarker(node);
            if (marker === null)
                return;
            const invalid = (() => {
                switch (marker.tag) {
                    case "$var":
                        return typeof marker.payload === "string" ? undefined : "a string name";
                    case "$oneOf":
                        return Array.isArray(marker.payload) ? undefined : "an array";
                    case "$regexp": {
                        if (typeof marker.payload !== "object" ||
                            marker.payload === null ||
                            typeof marker.payload.source !== "string" ||
                            typeof marker.payload.flags !== "string") {
                            return "string source and flags";
                        }
                        try {
                            new RegExp(marker.payload.source, marker.payload.flags);
                            return undefined;
                        }
                        catch {
                            return "valid regular-expression source and flags";
                        }
                    }
                    case "$is":
                        if (typeof marker.payload !== "string")
                            return "a string description";
                        return liveOf(node) === undefined ? "its definition-site matcher" : undefined;
                    case "$former":
                        return typeof marker.payload === "object" && marker.payload !== null
                            ? undefined
                            : "a former description";
                    case "$lit":
                        return typeof marker.payload === "object" && marker.payload !== null
                            ? undefined
                            : "an object literal";
                }
            })();
            if (invalid !== undefined) {
                throw new Error(`${kind} "${site}": marker "${marker.tag}" requires ${invalid}.`);
            }
            if (marker.tag === "$lit") {
                for (const value of Object.values(marker.payload)) {
                    this.assertPatternUsable(value, site, kind);
                }
            }
            return marker.tag === "$oneOf";
        });
    }
    lineRefPromise(op, diagnosticSite) {
        if (viewLineIR(op)) {
            const nested = liveOf(op) ?? this.definitions.viewNamed(op.view);
            return nested?.promise ?? "optional";
        }
        if (op.query === undefined)
            return "many";
        return (this.definitions.resolver.query(op.query.concept, op.query.query, diagnosticSite)
            .queryPromise ?? "many");
    }
}
